import React from 'react';import {Navigate,Route,Routes} from 'react-router-dom';import Layout from './layouts/Layout.jsx';import MemberLayout from './layouts/MemberLayout.jsx';import Login from './pages/Login.jsx';import Dashboard from './pages/Dashboard.jsx';import Books from './pages/Books.jsx';import Members from './pages/Members.jsx';import Loans from './pages/Loans.jsx';import Reservations from './pages/Reservations.jsx';import Fines from './pages/Fines.jsx';import Reports from './pages/Reports.jsx';import Settings from './pages/Settings.jsx';import Audit from './pages/Audit.jsx';import MemberDashboard from './pages/MemberDashboard.jsx';
class Boundary extends React.Component{constructor(p){super(p);this.state={error:null}}static getDerivedStateFromError(error){return{error}}componentDidCatch(e){console.error(e)}render(){return this.state.error?<div className="crash"><h2>Page error</h2><p>{this.state.error.message}</p><button className="btn" onClick={()=>location.reload()}>Reload page</button></div>:this.props.children}}
function Guard({children,role}){const token=localStorage.getItem('library_token');const user=JSON.parse(localStorage.getItem('library_user')||'{}');if(!token)return <Navigate to="/login" replace/>;if(role&&user.role!==role)return <Navigate to={user.role==='admin'?'/':'/my-account'} replace/>;return <Boundary>{children}</Boundary>}
function HomeRedirect(){const u=JSON.parse(localStorage.getItem('library_user')||'{}');return <Navigate to={u.role==='member'?'/my-account':'/'} replace/>}
export default function App(){return <Routes><Route path="/login" element={<Login/>}/><Route path="/" element={<Guard role="admin"><Layout/></Guard>}><Route index element={<Dashboard/>}/><Route path="books" element={<Books/>}/><Route path="members" element={<Members/>}/><Route path="loans" element={<Loans/>}/><Route path="reservations" element={<Reservations/>}/><Route path="fines" element={<Fines/>}/><Route path="reports" element={<Reports/>}/><Route path="audit" element={<Audit/>}/><Route path="settings" element={<Settings/>}/></Route><Route path="/my-account" element={<Guard role="member"><MemberLayout/></Guard>}><Route index element={<MemberDashboard/>}/></Route><Route path="/home" element={<Guard><HomeRedirect/></Guard>}/><Route path="*" element={<Navigate to="/home" replace/>}/></Routes>}
